# aeneid-056 (VII.706-817): t is cut from the edition by A.cut; l, i, n drafted from the Latin.
import sys, os
HERE = os.path.dirname(os.path.abspath(__file__)); sys.path.insert(0, HERE); sys.path.insert(0, os.path.join(HERE, '..', '..'))
import aeneid_lib as A

TITLE = 'Itala agmina. Turnus et Camilla'
PART = 'Turnus, Camilla and the End of the Muster (VII.706–817)'
TITLE_EN = 'Turnus, Camilla and the End of the Muster — Aeneid VII.706–817'
ABOUT = ("The second half of Virgil's catalogue of the Italian leaders who take the field against Aeneas, modelled on Homer's "
"catalogue of the ships in Iliad 2. Clausus comes first, leading the Sabines, the ancestor of the Claudian family of Virgil's own Rome; "
"then Halaesus, once a follower of Agamemnon, with the vine-growers and hill-folk of Campania; Oebalus, son of a king of Capri, "
"whose men fight with outlandish weapons; Ufens and his rough Aequian hunters, who plough under arms and live by plunder; and "
"Umbro, the Marsian priest who could charm snakes to sleep but could not heal himself of a Trojan wound. Virbius, son of "
"Hippolytus, gives Virgil the occasion for a myth: Hippolytus, killed by his own frightened horses, was brought back to life by "
"Diana and the healer Aesculapius, and hidden in the sacred grove of Aricia under a new name. Then comes Turnus himself, taller by "
"a head than all the rest, with a fire-breathing Chimaera on his helmet and the story of Io on his shield, followed by a cloud of "
"infantry from all Latium. Last of all rides Camilla, the Volscian warrior maiden, so swift she could run over standing corn without "
"bending it, and the whole countryside pours out to stare at her. With her, Book VII ends; her story is told in Book XI.")

U = [
(709, 'Sabinis.',
 "Look — of the Sabines' ancient blood, a great\ncolumn leading, Clausus, and of a great column himself the equal,\nfrom whom now the Claudian is spread both tribe and clan\nthrough Latium, since in a share Rome was given to the Sabines.",
 "And see, here is Clausus, of the ancient blood of the Sabines, leading a great column and himself the equal of a great column, the man from whom the Claudian tribe and clan now spread through Latium, ever since Rome was given to the Sabines to share.",
 """'Ecce', 'look!', the catalogue's way of bringing a new figure into view. 'agmen agens', 'driving a column', verb and noun from the same root ('ago'); the phrase returns for Camilla at 804. 'magni… agminis instar', 'the equal of a great column', 'instar' an indeclinable noun with the genitive: Clausus alone is worth an army. He is the legendary founder of the Claudii (Livy, from memory, tells of an Attus Clausus who came to Rome from the Sabine country with his clients in the first years of the Republic); the Claudii were the family of Livia's first husband and of her son Tiberius, Augustus's stepson, so Virgil is paying a compliment to the imperial house. 'tribus', the Claudian voting-tribe; 'gens', the clan. 'a quo', 'from whom'. 'postquam in partem data Roma Sabinis', 'since Rome was given to the Sabines for a share' (supply 'est'): after the war over the stolen Sabine women, Romulus shared the city with the Sabine king Titus Tatius. Virgil looks ahead from mythic time to 'nunc', his own day."""),
(711, 'Mutuscae;',
 "Together the huge Amiternian cohort, and the ancient Quirites,\nof Eretum the whole band, and of olive-bearing Mutusca;",
 "With him came the great cohort of Amiternum and the ancient men of Cures, the whole muster of Eretum and of Mutusca, the land of olives;",
 """'Una', the adverb, 'along with him'. No verb is expressed for the whole list down to 717: 'came' or 'marched' is supplied, a catalogue's habit. Amiternum, Eretum and Mutusca are Sabine towns in the hills north-east of Rome. The 'Quirites' here are the people of Cures, the Sabine town of Titus Tatius and of King Numa; the Romans traced their own civic name, Quirites, to it, which is why Virgil calls these men 'prisci', 'of old'. 'oliviferae', 'olive-bearing', one of the compound adjectives in '-fer' ('bearing') that Latin epic likes to coin; Sabine oil was famous. 'Ereti… Mutuscae' are genitives depending on 'manus'."""),
(714, 'Himellae,',
 "those who Nomentum city, who the Rosean fields of Velinus,\nwho of Tetrica bristling the crags and Mount Severus\nand Casperia inhabit, and Foruli and the river Himella,",
 "the men who dwell in the city of Nomentum and the Rosean fields by the Velinus, on the rugged crags of Tetrica and Mount Severus, in Casperia and Foruli and along the river Himella,",
 """The list turns to relative clauses, 'qui… qui… qui… colunt', 'those who inhabit…', with the antecedent ('the men') understood; the repeated 'qui' (anaphora) drives the roll-call on, and the one verb 'colunt' governs every accusative in the three lines. All are Sabine places. The 'Rosea rura' were the rich meadows by the Velinus near Reate (Rieti); Tetrica and Severus are mountains of the Sabine Apennines. 'horrentis', 'bristling', 'rugged', genitive singular agreeing with 'Tetricae'. 'Nomentum urbem', 'the city of Nomentum', the town's name in apposition, with elision."""),
(717, 'nomen:',
 "who the Tiber and Fabaris drink, whom cold sent\nNursia, and the Hortine levies and the peoples Latin,\nand whom, cutting between them, flows among the Allia, ill-omened name:",
 "those who drink the Tiber and the Fabaris, those whom chill Nursia sent, the levies of Horta and the Latin peoples, and those whose lands the Allia cuts through with its stream, a name of evil omen:",
 """'bibunt', 'drink', the poet's way of saying 'live beside' a river. The Fabaris (the Farfa) is a Sabine tributary of the Tiber; Nursia (Norcia) lies high in the Apennines, hence 'frigida'. 'classes' here is not 'fleets' but the old sense, 'levies', 'divisions of the people under arms' (Lewis & Short gives this as the original meaning). Horta (Orte) is a town on the Tiber; the Latin Library spells it 'Ortinae', the same place. 'quosque secans… interluit Allia', 'and those between whom the Allia flows, cutting through (their land)'. 'infaustum… nomen' stands in apposition to 'Allia': on the Allia the Gauls routed the Romans in 390 BC before sacking the city, and the anniversary was kept as an unlucky day in the calendar. The colon leads into the similes for the host's numbers."""),
(719, 'undis;',
 "as many as on the Libyan are rolled marble waves\nwhen savage Orion in wintry sets waters;",
 "as many as the waves that roll on the Libyan sea when fierce Orion sinks beneath the waters of winter;",
 """The first of two similes for numbers, both Homeric in kind (Homer likens the Greek host to leaves and flowers in spring, Iliad 2, from memory). 'quam multi… fluctus', 'as many as the waves (that)…', with 'they came' to be supplied before it. 'marmore', 'the marble', the gleaming surface of the sea, an epic word (the Greek 'marmaros' meant 'glittering'); 'Libyco', the sea off Africa. 'saevus ubi Orion', with 'ubi' postponed, as often in verse. The constellation Orion sets in November, at the start of the stormy season; 'conditur', 'hides himself', 'is buried'. Ilioneus called him 'nimbosus Orion', 'stormy Orion', at I.535."""),
(721, 'arvis.',
 "or when with the sun new thick are scorched the ears of grain\neither on the Hermus's plain or on Lycia's yellowing fields.",
 "or as the close-packed ears of corn that ripen in the early summer sun on the plain of the Hermus or in the golden fields of Lycia.",
 """'vel cum', 'or (as many as) when', the second term of the comparison, with 'as many' carried over from 'quam multi'. 'sole novo', 'with the new sun', the fresh heat of early summer; 'torrentur', 'are scorched', ripening for harvest. The Hermus is a river of Lydia in Asia Minor with a famous plain, and Lycia lies to the south; both were rich corn-lands. 'flaventibus', 'turning yellow', present participle of 'flaveo'. 'aut… aut', 'either… or'; note the elision 'campo aut'."""),
(722, 'tellus.',
 "Shields resound, and with the beat of feet terrified the earth.",
 "Shields ring, and the earth trembles in terror at the tramp of feet.",
 """The paragraph closes on sound. 'pulsu pedum', 'with the beating of feet'. 'conterrita tellus', supply 'est': the earth itself is 'thoroughly terrified', 'con-' intensifying the verb. Homer too makes the earth groan under the marching host in his catalogue (Iliad 2, from memory)."""),
(725, 'populos,',
 "Next Agamemnon's man, of the Trojan name the foe,\nto the chariot yokes Halaesus his horses, and for Turnus fierce\na thousand he sweeps along peoples,",
 "Next Halaesus, Agamemnon's man and an enemy of the Trojan name, yokes his horses to his chariot and sweeps along a thousand fierce tribes to fight for Turnus,",
 """'Hinc', 'next', in the order of the catalogue. 'Agamemnonius', 'Agamemnon's', an adjective doing the work of a genitive: Halaesus was said to be a companion of Agamemnon (Servius, from memory, records the story) who came to Italy after the king's murder and founded Falerii. 'Troiani nominis hostis', in apposition: he fought the Trojans at Troy and fights them still. 'curru iungit… equos', 'yokes his horses to the chariot', 'curru' the old dative in '-u' (= 'currui'). 'ferocis… populos', accusative plural in '-is', Greenough's spelling (= 'feroces'). 'Turno', dative of advantage, 'for Turnus'. 'mille', 'a thousand', poetic for 'very many'. 'rapit', 'snatches along', hurries them off to war."""),
(727, 'patres,',
 "who turn the happy-for-Bacchus\nMassic slopes with mattocks, and whom from the hills high\nthe Auruncan fathers sent,",
 "men who turn with their mattocks the Massic slopes so kind to Bacchus, men whom the Auruncan elders sent down from their high hills,",
 """'qui' is held back to the second line: 'qui vertunt… Massica', 'who turn (the soil of) the Massic (slopes)'. Mount Massicus in northern Campania grew one of the best Italian wines, so its slopes are 'felicia Baccho', 'fruitful for Bacchus', with 'Baccho' dative; 'Massica' is a neuter plural adjective with 'arva' or 'iuga' understood. 'rastris', 'with heavy hoes', the vine-dresser's tool. The Aurunci were an old people of the coast between Latium and Campania; 'patres', their elders. 'misere' = 'miserunt', the short perfect in '-ere' you have met constantly."""),
(730, 'manus.',
 "and the Sidicine near by\nplains who and Cales leave, and of the river shallow\nthe neighbour, Volturnus, and alike the Saticulan rough\nand of the Oscans the band.",
 "those who have left the Sidicine plains near by and Cales, the dweller by the shallows of the Volturnus, and with them the rough Saticulan and the bands of the Oscans.",
 """'Sidicinaque… aequora quique Cales linquunt', 'and those who leave the Sidicine plains near by, and Cales': both accusatives are objects of 'linquunt'. The Sidicini lived round Teanum in northern Campania; Cales (Calvi), another Campanian town, was also known for its wine. 'linquunt', 'leave', to go to war. 'amnis… vadosi accola Volturni', 'the dweller beside the shallow river Volturnus': 'accola' is a noun, 'one who lives by'. It and 'Saticulus asper', 'the rough man of Saticula', are collective singulars standing for whole peoples. The Oscans were the old Italic people of Campania, whose language was still spoken in parts of Italy in Virgil's day."""),
(731, 'flagello;',
 "Smooth-rounded are aclydes to them\nfor weapons, but these to a pliant it is their custom to fasten thong;",
 "Their weapons are rounded clubs called aclydes, which it is their custom to fasten to a pliant thong;",
 """'illis', dative of possession: 'to them are aclydes as weapons', 'they have aclydes'. 'aclydes' is a Greek word (nominative plural) for some short throwing-club or dart; the old commentators were themselves unsure what it was. 'teretes', 'rounded', 'smooth'. 'tela' is the predicate: 'their weapons are aclydes'. 'haec… mos est aptare… flagello', 'it is the custom to fasten these to a pliant thong', 'flagello' dative with 'aptare': the thong let them hurl the club and pull it back."""),
(732, 'enses.',
 "their lefts a buckler covers; sickle-curved, hand to hand, the swords.",
 "a light buckler guards the left arm, and for close fighting they have swords curved like sickles.",
 """'laevas', 'left (hands)', with 'manus' understood. 'caetra', a small, light leather shield of the kind used by Spaniards and Africans (Lewis & Short). 'falcati… enses', 'swords curved like a sickle' ('falx'); the verb is left out ('they have', or 'serve them'). 'comminus', 'hand to hand', in contrast with the thrown aclydes. Virgil likes to give each people its own outlandish gear; there is more in the next paragraph."""),
(736, 'senior;',
 "Nor you, by songs our, unsung will go away,\nOebalus, whom to have begotten Telon on the Sebethid nymph\nis said, of the Teleboans Capri when, as his kingdom, he held,\nnow growing old;",
 "Nor shall you go unsung in my verses, Oebalus, whom Telon is said to have fathered on the nymph Sebethis when he ruled Capri, the Teleboans' kingdom, already well on in years;",
 """Apostrophe: the poet turns to speak to his hero, 'nor shall you go away unsung in our songs', a way of honouring a minor figure. 'carminibus nostris', 'our songs', the poet's plural; 'indictus', 'unspoken of', 'unsung'. 'quem generasse Telon… fertur', the personal construction: 'whom Telon is said to have begotten'. 'Sebethide nympha', ablative of source, 'from the nymph Sebethis', daughter of the Sebethus, a stream at Naples. 'Teleboum' = 'Teleboarum', the old genitive plural in '-um': the Teleboans, a people from western Greece said to have settled Capreae (Capri). 'Capreas… regna', 'Capri, his kingdom', 'regna' in apposition. 'iam senior', 'already rather old', with 'senior' the comparative; it goes with Telon."""),
(740, 'Abellae,',
 "with his father's but not also the son fields\ncontent, widely even then in his sway held down\nthe Sarrastian peoples and the plains which waters the Sarnus,\nand those who Rufrae and Batulum hold and the fields of Celemna,\nand whom apple-bearing look down upon the walls of Abella,",
 "but the son, not content like him with his father's lands, held wide sway even then over the Sarrastian peoples and the plains watered by the Sarnus, the men who hold Rufrae and Batulum and the fields of Celemna, and those on whom the walls of Abella, rich in apples, look down,",
 """'sed non et filius', 'but not the son also' (content), with 'et' = 'etiam'; 'patriis… arvis contentus', ablative with 'contentus'. The father stayed on his island, the son crossed to the mainland and ruled in Campania. 'late… dicione premebat', 'held them down far and wide under his rule'. 'quae rigat aequora Sarnus', 'the plains which the Sarnus waters', the antecedent drawn into the relative clause; the Sarnus (Sarno) flows past Pompeii into the Bay of Naples, and the Sarrastes were the people of its valley. Rufrae, Batulum and Celemna are small Campanian places now hardly known. 'maliferae… Abellae', 'apple-bearing Abella' (Avella), famous for its orchards, and especially for nuts: Lewis & Short derives 'avellana', the hazelnut, from the town. 'despectant', 'look down upon', the frequentative of 'despicio'."""),
(743, 'ensis.',
 "in the Teutonic fashion accustomed to hurl cateias,\ncoverings to whom of heads is bark torn from the cork-oak,\nand bronze-plated gleam the targes, gleams the bronze sword.",
 "men used to hurling the cateia in the German fashion, whose helmets are bark stripped from the cork-oak, whose crescent shields flash with bronze, and the bronze sword flashes.",
 """'soliti torquere', 'accustomed to hurl' (literally 'to spin', 'whirl'), describing all these peoples. 'cateias', a Celtic throwing-weapon, perhaps a kind of curved club; 'Teutonico ritu', 'in the German manner', the Teutones being a by-word for northern savagery since Marius's wars. 'quis' = 'quibus', the old dative plural of the relative, dative of possession: 'to whom the coverings of their heads (are) bark…'. 'raptus de subere cortex', 'bark torn from the cork-oak'. 'peltae', light crescent-shaped shields (a Greek word; the Thracian targe). 'aerataeque… aereus', 'bronze-plated… bronze': the repeated 'micant… micat' ends the paragraph on the glint of bronze."""),
(745, 'armis;',
 "And you mountainous sent into battles Nersae,\nUfens, distinguished in fame and in fortunate arms;",
 "You too, Ufens, mountainous Nersae sent to the war, a man renowned in story and for his success in arms;",
 """Another apostrophe, 'et te', 'you too', as for Oebalus at 733. 'Nersae', a hill town of the Aequi in the central Apennines, nominative plural like 'Athenae'. 'misere' = 'miserunt' again. 'insignem fama et felicibus armis', 'distinguished by repute and by fortunate arms', ablatives of respect. Ufens is also the name of a river in southern Latium (802)."""),
(747, 'glaebis.',
 "rough above all, his the race, and used to much\nhunting of the woods, the Aequian, with hard clods.",
 "his people are the Aequiculi, rough above all others, hardened to long hunting in the forests, on a stubborn soil.",
 """'cui… gens', 'to whom (was) a race', dative of possession: 'whose people were…'. 'Aequicula', the adjective 'of the Aequiculi', holds back the name to the end. The Aequi were among Rome's oldest enemies, in the hills east of the city. 'praecipue', 'especially', 'above the rest'. 'multo venatu', ablative with 'adsueta', 'used to much hunting' ('venatu' from the fourth-declension 'venatus'). 'duris… glaebis', ablative of description or of place, 'with hard clods', a stony, stubborn land. 'cui' counts as one syllable here, as often."""),
(749, 'rapto.',
 "Armed they work the earth, and always fresh\nto haul in it pleases them plunder, and to live on what is seized.",
 "They till the ground with arms on, and it is always their delight to bring home fresh plunder and to live on what they take.",
 """'Armati terram exercent', 'armed, they work the land': frontier folk who plough with weapons on. 'iuvat', impersonal, 'it pleases (them)', with the infinitives 'convectare' (frequentative, 'keep bringing in') and 'vivere'. 'recentis… praedas', accusative plural in '-is' again. 'vivere rapto', 'to live on what is seized', 'rapto' a neuter participle used as a noun, ablative of means. Virgil gives almost the same line again in Book IX, in the boast of the Rutulian Numanus about Italian toughness."""),
(751, 'oliva.',
 "Moreover, also from the Marruvian came race a priest,\nwith foliage above his helmet and with fortunate adorned olive.",
 "There came too a priest from the Marruvian people, his helmet crowned with a wreath of fruitful olive.",
 """'Quin et', 'moreover', 'what is more', bringing in a further and striking figure. Marruvium was the chief town of the Marsi by Lake Fucinus; the Marsi were famous as snake-charmers and dealers in herbs and spells. 'fronde… et felici… oliva', 'with foliage and fruitful olive', two nouns for one idea, 'with a wreath of fruitful olive' (hendiadys; you will meet it often). 'comptus', 'adorned', past participle of 'como', with 'super galeam', 'above his helmet': a priest in arms wears his wreath over his helmet. Note the elision 'galeam et'."""),
(755, 'levabat.',
 "By King Archippus's sending, most valiant Umbro,\nupon the viper race and the heavily breathing water-snakes\nto sprinkle who sleep with chant and with hand was accustomed,\nand soothed their angers and their bites by skill relieved.",
 "He came at the bidding of King Archippus — Umbro, bravest of men, who used to shed sleep on the breed of vipers and on foul-breathing water-snakes with his chant and his touch, soothing their rage and easing their bites by his art.",
 """Greenough prints a full stop after 'oliva' at 751 and a capital 'Archippi', so these four lines stand without a main verb; the sense wants a comma, with 'Archippi regis missu' telling how the priest came and 'fortissimus Umbro' naming him in apposition to 'sacerdos'. It is doubtful whether the stop is a misprint, since the capital that follows agrees with it, so the print is kept as it stands; read 'venit' from 750 as understood ('he came'). 'missu', 'by the sending', 'at the bidding', a fourth-declension noun found only in this ablative. 'vipereo generi… hydris', datives with 'spargere somnos', 'to sprinkle sleep upon'. 'graviter spirantibus', 'breathing heavily', with foul, poisonous breath. 'qui' is held back to the third line. 'cantuque manuque', the double '-que… -que', 'both by chant and by touch'. 'solebat… mulcebat… levabat', imperfects of habit, 'used to'."""),
(758, 'herbae.',
 "But not of a Dardan to heal spear-point the stroke\nwas he able, nor him helped against wounds the chants\nsleep-bringing and on the Marsian sought mountains herbs.",
 "But he had no power to heal the stroke of a Trojan spear-point: no sleep-bringing chants could help him against his wounds, nor herbs gathered on the Marsian mountains.",
 """The healer cannot heal himself: Virgil tells Umbro's fate in advance, and these lines are his epitaph. 'Dardaniae… cuspidis', 'of a Dardan spear-point', Dardan meaning Trojan, after Dardanus, founder of their royal line. 'medicari… ictum', 'to heal the blow', 'medicor' a deponent verb. 'evaluit', 'was strong enough', 'availed'. 'iuvere' = 'iuverunt'. 'in volnera', 'for (against) wounds'; 'volnera' is Greenough's older spelling of 'vulnera'. 'somniferi', 'sleep-bringing', another '-fer' compound. 'Marsis… montibus', ablative of place with 'quaesitae', 'sought on the Marsian hills'."""),
(760, 'lacus.',
 "You the grove of Angitia, glassy you Fucinus with its wave,\nyou the clear wept lakes.",
 "For you the grove of Angitia wept, for you the Fucine lake with its glassy water, for you the clear lakes mourned.",
 """The poet turns again to address the dead man: 'te… te… te', the threefold anaphora of lament, and the landscape itself weeps ('flevere' = 'fleverunt', one verb for all three subjects). Angitia was a Marsian goddess of healing and snake-lore, with a grove near Lake Fucinus, the centre of the Marsi's country (the lake was drained in the nineteenth century). 'vitrea… unda', 'with glassy water', ablative of description. Line 760 is a half-line, one of those Virgil left unfinished at his death; the sense ends with it."""),
(764, 'Dianae.',
 "There went too Hippolytus's offspring, most handsome, to the war,\nVirbius, splendid, whom his mother Aricia sent,\nreared in Egeria's groves the moist around\nshores, where rich and easily-appeased is the altar of Diana.",
 "There went to the war also Hippolytus's son, the handsome Virbius, sent out in splendour by his mother Aricia; he had been reared in Egeria's groves round the marshy shores, where Diana's altar stands, rich with offerings and gracious to those who pray.",
 """'Ibat… bello', 'went to the war', 'bello' a poetic dative of goal. 'proles', 'offspring'. 'mater Aricia': Aricia (Ariccia) was the town in the Alban Hills beside the Lake of Nemi, with its famous grove of Diana; Virgil makes the town, or a nymph of that name, Virbius's mother. 'insignem', 'splendid', in fine armour. 'eductum', 'reared'. 'Egeriae lucis umentia circum litora', 'in Egeria's groves, around the moist shores', with 'circum' placed after its adjective. Egeria, the water-nymph who counselled King Numa, had a spring in Diana's grove at Nemi. 'pinguis… et placabilis ara', 'a rich and easily appeased altar', supply 'est': 'pinguis' with the fat of sacrifices, 'placabilis', readily won over. Note the elision 'eductum Egeriae'."""),
(769, 'Dianae.',
 "For they say in story that Hippolytus, after by the craft of his stepmother\nhe fell, and the penalty his father sought had paid in full with his blood,\nby panicked torn apart horses, to the stars again\nof the upper sky and under the airs above of heaven came,\nby Paeonian called back herbs and by the love of Diana.",
 "For the story goes that when Hippolytus had fallen through his stepmother's scheming and paid with his blood the penalty his father called down, torn apart by his frightened horses, he came back again to the stars of heaven and the air of the world above, recalled to life by healing herbs and by the love of Diana.",
 """The myth behind Virbius. Hippolytus, son of Theseus, was loved by his stepmother Phaedra; when he refused her she accused him falsely to his father, and Theseus cursed him. A monster sent from the sea frightened his chariot-horses, and he was dragged to death (the story of Euripides's Hippolytus). 'ferunt fama… Hippolytum… venisse', 'they say by report that Hippolytus came', accusative and infinitive. 'arte novercae', 'by his stepmother's craft'. 'occiderit… explerit', perfect subjunctives in a subordinate clause of reported speech; 'explerit' is the contracted form of 'expleverit'. 'patrias… poenas', 'the punishment his father called for'. 'turbatis… equis', ablative of means, 'by his panic-stricken horses'; 'distractus', 'torn apart'. 'Paeoniis… herbis', 'by Paeonian herbs': Paeon was the physician of the gods, so 'Paeonian' means 'healing'. The healer here is Aesculapius (next lines). Elisions 'fama Hippolytum', 'postquam arte'."""),
(773, 'undas.',
 "Then the father almighty, indignant that anyone from the shades\nmortal below to the lights should rise of life,\nhimself the finder of a cure such and of the art\nwith his thunderbolt, Phoebus-born, to the Stygian thrust down waters.",
 "Then the almighty father, outraged that any mortal should rise from the shades below to the light of life, himself hurled down with his thunderbolt to the waters of the Styx the son of Phoebus who had found such a remedy and such an art.",
 """'indignatus… surgere', 'resenting that anyone… should rise', accusative and infinitive after a verb of feeling. 'ab umbris… infernis', 'from the shades below'; 'lumina vitae', 'the light of life'. 'repertorem medicinae talis et artis', 'the discoverer of such a cure and such a skill'. 'Phoebigenam', 'Phoebus-born', a compound found perhaps only here: Aesculapius (Asclepius), son of Apollo, whom Jupiter killed with lightning for raising the dead (the tale is told by Pindar, Pythian 3, from memory). 'ipse', the god himself. 'detrusit', 'thrust down'. Note the elisions 'aliquem indignatus', 'mortalem infernis'."""),
(777, 'esset.',
 "But Trivia Hippolytus in secret, the kindly one, hides away\nabodes, and to the nymph Egeria and to her grove consigns,\nwhere alone in woods Italian, unknown, his life\nhe might pass, and where with changed name Virbius he might be.",
 "But kindly Diana hid Hippolytus away in a secret dwelling and entrusted him to the nymph Egeria and her grove, where he might live out his days alone and unknown in the woods of Italy and, under a changed name, be Virbius.",
 """'Trivia', 'goddess of the three ways', a title of Diana as Hecate, worshipped where three roads meet. 'alma', 'kindly', 'nurturing'. 'recondit', 'hides away', and 'relegat', 'consigns', historic presents. 'secretis… sedibus', ablative of place. 'ubi… exigeret… esset', subjunctives in a relative clause of purpose: 'where he might live out… and be'. 'aevom' is Greenough's spelling of 'aevum', 'life-time' (the old '-om' after 'v'). 'ignobilis', 'unknown', 'unrenowned'. 'verso… nomine', 'with his name changed', ablative absolute. The ancients explained 'Virbius' as 'vir bis', 'twice a man', because he lived twice (an etymology reported by Servius, from memory); Virgil does not spell it out. Elisions 'Trivia Hippolytum', 'nymphae Egeriae'."""),
(780, 'marinis.',
 "Whence also from the temple of Trivia and her groves hallowed\nhorn-footed are kept away horses, because on the shore the chariot\nand the youth, by monsters terrified, they spilled out, of the sea.",
 "That is why horses with their horny hooves are kept out of Trivia's temple and her sacred groves: in terror of the monster from the sea they flung the chariot and the young man out upon the shore.",
 """'Unde', 'from which cause', 'and that is why'. The story explains a real rule of cult: no horse might enter Diana's grove at Aricia (a tale of origins, what the Greeks called an 'aetion'). 'templo… lucisque', ablatives of separation with 'arcentur', 'are kept from'. 'cornipedes', 'horn-footed', an old epic compound for hoofed horses. 'monstris… marinis', the sea-monster, ablative of cause with 'pavidi', 'terrified by'; the plural is poetic. 'effudere' = 'effuderunt', 'poured out', 'threw out'. 'litore', ablative of place, 'on the shore'. Elisions 'Unde etiam', 'pavidi effudere'."""),
(782, 'ruebat.',
 "The son, of the burning none the less over the level of the plain,\nexercised his horses and in his chariot into wars rushed.",
 "Yet his son, for all that, drove his horses over the sun-scorched plain and charged into battle in his chariot.",
 """The paragraph returns from myth to the catalogue with a pointed contrast: the father died by his horses, yet the son drives a chariot. 'haud setius', 'not otherwise', 'none the less', 'setius' a comparative adverb. 'ardentis… aequore campi', 'over the level of the burning plain', 'ardentis' genitive singular with 'campi'. 'exercebat', 'kept exercising', 'trained'. 'curru', 'in his chariot', ablative. 'in bella ruebat', 'was rushing into wars', the imperfect of the scene as it unfolds."""),
(784, 'est.',
 "Himself among the foremost, of surpassing body, Turnus\nmoves to and fro, arms holding, and by a whole head above is.",
 "Turnus himself, superb in stature, moves among the foremost with his weapons in his hand, taller than all the rest by a full head.",
 """'Ipse', 'Turnus himself', the leader for whom all these have mustered, saved for near the end as the climax of the catalogue. 'praestanti corpore', ablative of quality, 'of outstanding build'. 'vertitur', 'turns himself about', 'moves to and fro', a passive used in a middle sense. 'toto vertice supra est', 'is above (them) by his whole head', 'vertice' ablative of the degree of difference; Homer says much the same of Ajax and of Agamemnon (Iliad 3, from memory). Note the play 'vertitur… vertice', and the elisions 'Ipse inter', 'supra est'."""),
(786, 'ignis:',
 "Whose, with triple maned crest, helmet high, a Chimaera\nholds up, Aetnaean breathing from its jaws fires:",
 "His tall helmet, shaggy with a triple crest, bears a Chimaera breathing Etna's fires from her jaws:",
 """'Cui', a connecting relative and dative of possession, 'his'. 'triplici crinita iuba', 'maned with a triple crest', 'crinita' agreeing with 'galea'. The Chimaera was the fire-breathing monster of Lycia, lion in front, serpent behind and goat between, killed by Bellerophon; one stood among the monsters at the gate of the underworld in Book VI. 'Aetnaeos… ignis', 'fires like Etna's', accusative plural in '-is'. 'efflantem faucibus', 'breathing out from her jaws'. The emblem fits its wearer: Turnus is the fire of this war. Note the elision 'galea alta'."""),
(788, 'pugnae.',
 "the more so she roaring and with grim wild flames,\nthe more with shed grow savage blood the battles.",
 "and the more the fighting grows savage with the shedding of blood, the louder she roars, the wilder she rages with her deadly flames.",
 """'tam magis… quam magis', 'the more… the more', an old correlative pair in place of the usual 'quo magis… eo magis'. 'illa', the Chimaera; supply 'est': she seems to rage the more as the fighting turns bloody, a crest that comes alive in battle. 'fremens', 'roaring'; 'effera', 'wild', 'savage'. 'tristibus… flammis', 'with grim flames', ablative of cause. 'crudescunt', 'grow raw', 'grow fierce', an inceptive in '-sco'. 'effuso… sanguine', 'with blood poured out', ablative of cause or means."""),
(792, 'urna.',
 "But the smooth shield, with uplifted horns, Io\nin gold emblazoned, already with bristles covered, already a cow\n(a mighty theme), and the guardian of the maiden, Argus,\nand from an embossed, a river pouring, father Inachus, urn.",
 "But his polished shield was emblazoned in gold with Io, her horns raised, already covered with coarse hair and already a heifer — a mighty theme — and Argus, the maiden's guardian, and her father Inachus pouring out his river from a figured urn.",
 """'levem' with a long e ('levis', 'smooth', polished), not 'levis', 'light'. 'Io… insignibat', 'Io marked the shield', 'insignibat' the old imperfect in '-ibat' for '-iebat'. The story: Jupiter loved Io, daughter of the river-god Inachus of Argos; she was turned into a heifer, and jealous Juno set hundred-eyed Argus to guard her. 'iam saetis obsita, iam bos', 'already overgrown with bristles, already a cow': the artist catches her in mid-change. 'argumentum ingens', in brackets, 'a mighty subject' for a shield, and a pointed one: Io is an Argive heroine, and Inachus was named among Turnus's own forefathers at 7.371–372; the emblem also recalls Juno, whose hatred drives this war. 'caelata… urna', 'from an embossed urn', the river-god's emblem. 'amnem fundens', 'pouring out his river'. Note the elision 'caelataque amnem'."""),
(796, 'Labici;',
 "Follows a cloud of foot-soldiers, and shield-bearing over the whole\ncolumns crowd thick plain, and the Argive youth\nand Auruncan bands, Rutulians and old Sicanians\nand Sacranian lines and painted as to shields Labicans;",
 "A cloud of infantry follows, and shield-bearing columns crowd thick over all the plain: the Argive youth, the Auruncan bands, the Rutulians and the ancient Sicanians, the Sacranian ranks and the Labicans with their painted shields;",
 """'nimbus peditum', 'a storm-cloud of foot-soldiers', a bold metaphor (Homer too speaks of a cloud of infantry, Iliad 4, from memory). 'densentur', 'are packed close', from 'denseo', an older by-form of 'denso'. 'totis… campis', 'over the whole plain', ablative of place without 'in'. 'Argiva pubes', the Argive youth of Ardea, Turnus's city, said to have been founded by Danae from Argos (7.410). The Sicani were held to be an old people who lived in Latium before crossing to Sicily; the Sacrani are an obscure people of early Latium; Labici was a town in the Alban Hills. 'picti scuta', 'painted as to their shields', the Greek accusative of respect (the part affected), common in Virgil."""),
(800, 'luco;',
 "who the glades, Tiber, your and the sacred of the Numicus\nshore plough, and the Rutulian work with the share hills\nand Circe's ridge; over whose fields Jupiter of Anxur\npresides and, in her green rejoicing, Feronia grove;",
 "men who plough your glades, Tiber, and the sacred banks of the Numicus, who work with the share the Rutulian hills and Circe's headland, whose fields are ruled by Jupiter of Anxur and by Feronia, glad in her green grove;",
 """Apostrophe to the river: 'Tiberine', vocative, 'O Tiber'. 'saltus… tuos', 'your glades'. 'arant… exercent', 'plough… work': even woodland and shore are farmed. The Numicus was a small river near Lavinium, holy because Aeneas was said to have vanished in it at his death (a story Livy and others tell, from memory). 'vomere', 'with the ploughshare'. 'Rutulos… colles', 'the Rutulian hills' (the Latin Library prints 'collis', no change of sense). 'Circaeum iugum', the headland of Circeii, Circe's home, passed by the Trojans at the start of this book. 'quis' = 'quibus' again, with 'arvis': 'over whose fields', dative with 'praesidet'. Anxur (Terracina) worshipped a boyish Jupiter; Feronia, an old Italian goddess of groves, had a shrine and spring near there (Horace washes in it on his journey to Brundisium, Satires 1.5, from memory)."""),
(802, 'Ufens.',
 "where of Satura lies the black marsh, and cold through the lowest\nseeks its way valleys, and into the sea hides itself the Ufens.",
 "where the black marsh of Satura lies, and the cold Ufens seeks its way along the valley floors and buries itself in the sea.",
 """'qua', 'where', the relative adverb. The 'Saturae palus' is part of the Pontine Marshes south-east of Rome, a byword for fever until they were drained in the twentieth century. 'per imas… vallis', 'through the lowest valleys', 'vallis' accusative plural in '-is'. 'conditur', 'hides itself', as Orion did at 719. 'gelidus' waits for its noun 'Ufens', held back to the very end of the line and the paragraph; the river shares its name with the chieftain of 745."""),
(807, 'ventos.',
 "Over these arrives, of the Volscian race, Camilla,\na column leading of horsemen and blooming with bronze troops,\na woman-warrior, not she to the distaff or the wool-baskets of Minerva\nher womanly having trained hands, but battles, a maiden,\nhard to endure and in the running of her feet to outstrip the winds.",
 "Last of all comes Camilla, of the Volscian nation, leading her column of horsemen and troops bright with bronze, a warrior woman: she had never trained her woman's hands to Minerva's distaff and wool-baskets, but, maiden though she was, to endure hard battle and to outrun the winds on her racing feet.",
 """'Hos super', 'over and above these', 'besides these', with 'super' placed after its noun. The Volsci were a people of southern Latium. The catalogue that opened on Mezentius, scorner of the gods, ends on a figure of wonder; Camilla's full story is told in Book XI. 'agmen agens', as of Clausus at 707. 'florentis aere catervas', 'troops blooming with bronze', 'florentis' accusative plural in '-is'. 'bellatrix', 'woman-warrior', a feminine agent noun. 'colo calathisve Minervae', datives with 'adsueta': the distaff and wool-baskets belong to Minerva, goddess of women's crafts. 'non illa… adsueta manus', 'she not having trained her hands', 'manus' the accusative object of a participle used in a middle sense. 'virgo', 'a maiden', is pointed: a girl who chose war. 'pati… praevertere', infinitives with 'adsueta' understood, 'trained to endure… to outstrip'."""),
(811, 'plantas.',
 "She either of untouched corn across the topmost would fly\nblades, nor the tender with her running would have bruised ears,\nor the sea through the middle, on the wave poised swelling,\nwould make her way, nor would wet her swift in the water soles.",
 "She could have flown over the tips of a field of standing corn and never bruised the tender ears in her running, or sped her way through the midst of the sea, poised on the swelling wave, and never wet her swift feet in the water.",
 """Hyperbole in potential subjunctives: 'volaret… laesisset… ferret… tingueret', 'she would fly… would not have harmed…'; the pluperfect 'laesisset' looks at the harm as never done. 'intactae segetis… summa gramina', 'the topmost blades of uncut corn'. The picture goes back to Homer's mares of Erichthonius, which ran over the ears of corn without breaking them and over the crests of the sea (Iliad 20, from memory). 'fluctu suspensa tumenti', 'held up on the swelling wave'. 'ferret iter', 'would make her way'. 'celeris' most naturally goes with 'plantas', 'her swift soles' (accusative plural in '-is'), though as a feminine nominative singular it could describe Camilla herself. 'tingueret' is Greenough's spelling of 'tingeret' (the Latin Library's form), 'would wet'."""),
(813, 'euntem,',
 "Her all, from houses and fields poured out, the youth\nand the throng marvels at of mothers, and gazes after her going,",
 "All the young men stream out of houses and fields to marvel at her, and the mothers crowd to gaze after her as she passes,",
 """'Illam… euntem', 'her as she goes', framing the two lines. 'omnis… iuventus', 'all the young people', a collective singular, 'omnis' nominative singular here. 'tectis agrisque', ablatives of separation with 'effusa', 'poured out of houses and fields'. 'turba… matrum', 'the throng of mothers'. 'miratur… prospectat', singular verbs with the nearer subject. 'prospectat', 'looks out after', 'watches her go', a frequentative. Elisions 'Illam omnis', 'matrum et'."""),
(817, 'myrtum.',
 "with thunderstruck gaping minds, how the royal with purple\nveils honour her smooth shoulders, how a clasp her hair\nwith gold intertwines, how a Lycian she carries herself quiver\nand a shepherd's, with a point fixed on, myrtle.",
 "open-mouthed, their minds dazed with wonder, at how the royal honour of purple drapes her smooth shoulders, how a clasp of gold binds up her hair, how she carries a Lycian quiver and a shepherd's staff of myrtle tipped with a spear-head.",
 """'attonitis inhians animis', 'gaping with thunderstruck minds', 'inhians' singular with 'iuventus'. 'ut… velet… internectat… gerat', indirect questions after 'miratur', 'how…', with the subjunctive: the watchers wonder at each detail in turn. 'regius… honos… ostro', 'the royal glory of purple', 'ostro' ablative, the purple dye of the murex shell. 'levis umeros', 'her smooth shoulders', accusative plural ('levis' with a long e, as at 789). 'fibula', 'brooch', 'clasp'; 'auro', 'with gold'. 'Lyciam… pharetram', 'a Lycian quiver', Lycia being famous for archers. 'ipsa', 'she herself'. 'pastoralem… myrtum', 'a shepherd's myrtle', a staff of myrtle wood, which was used for spear-shafts, 'praefixa cuspide', 'with a point fixed on the end'. Book VII ends here: the war is mustered, and Book VIII turns to Aeneas."""),
]

P = A.part('aeneid-056'); L = A.lines_of(P); paras = {l['n'] for l in L if l['p']}
cuts = A.cut(P, [(u[0], u[1]) for u in U])
sents = []; prev_end_line = None
for (t, ln), (_, _t, l, i, n) in zip(cuts, U):
    u = {'t': t, 'l': l, 'i': i, 'n': n}
    if prev_end_line != ln and ln in paras: u['p'] = True
    u['v'] = True; u['ln'] = ln; sents.append(u)
    prev_end_line = ln + t.count('\n')
    if t.count('\n') != l.count('\n'): print('LINE COUNT', ln, repr(t[:30]), t.count('\n'), l.count('\n'))
    if t.count('\n') > 4: print('TOO LONG', ln)
    if '\n' in i: print('NEWLINE IN i', ln)
A.jdump({'title': TITLE, 'titleEn': TITLE_EN, 'part': PART, 'about': ABOUT, 'sentences': sents}, os.path.join(HERE, 'units.json'))
print(len(sents), 'units')
